-- Resumen
select 'productos' as tabla, count(*) from public.productos union all select 'colores', count(*) from public.colores
union all select 'presentaciones', count(*) from public.presentaciones union all select 'clientes', count(*) from public.clientes
union all select 'precios vigentes', count(*) from public.precios where vigente_hasta is null
union all select 'precios en historial', count(*) from public.precios where vigente_hasta is not null
union all select 'alertas para socios', count(*) from public.alertas;
